#!/usr/bin/env node
/*
 * Bookam mobile app - polish + working Refine Search (consolidated).
 * Run once from the project root:   node apply-bookam-polish.js
 *
 * Includes everything from the earlier polish update, plus:
 *   - Refine Search now actually works: a real draggable two-thumb price
 *     slider, and every filter (type, area, price, amenities, rating,
 *     verified) is applied to the live search results when you tap
 *     "Show Properties".
 *   - Verified Only is checked by default on the filter screen.
 *   - Rating stars are gold everywhere.
 *   - Logging out now shows a "You've been logged out" confirmation.
 *
 * This is the ONLY script you need to run - it supersedes the earlier ones.
 * After it runs:
 *   git add -A && git commit -m "working refine search, gold ratings, logout toast" && git push
 * Then press r in the Expo terminal to reload.
 */
const fs = require('fs');
const path = require('path');

const FILES = {
  "app/tabs/home.tsx": "",
  "app/tabs/explore.tsx": "",
  "app/tabs/_layout.tsx": "",
  "app/tabs/profile.tsx": "",
  "app/search/filter.tsx": "",
  "app/booking/detail-active.tsx": "",
  "app/booking/detail-review.tsx": "",
  "lib/api.ts": "",
  "lib/searchFilters.ts": ""
};

for (const [rel, data] of Object.entries(FILES)) {
  const full = path.join(__dirname, rel);
  fs.mkdirSync(path.dirname(full), { recursive: true });
  fs.writeFileSync(full, Buffer.from(data, 'base64'));
  console.log('  wrote  ' + rel);
}
console.log('\nDone. Next:');
console.log('  git add -A && git commit -m "working refine search, gold ratings, logout toast" && git push');
console.log('  Press r in the Expo terminal to reload.');